'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Complex64Array = require( '@stdlib/array/complex64' );
var accumulateUnary = require( './../lib' );


// FUNCTIONS //

/**
* Adds two values.
*
* @private
* @param {number} acc - accumulated value
* @param {number} x - input value
* @returns {number} sum
*/
function add( acc, x ) {
	return acc + x;
}

/**
* Multiplies two values.
*
* @private
* @param {number} acc - accumulated value
* @param {number} x - input value
* @returns {number} product
*/
function multiply( acc, x ) {
	return acc * x;
}

/**
* Sums the real component of a complex number.
*
* @private
* @param {number} acc - accumulated value
* @param {Complex} x - input value
* @returns {number} sum
*/
function sumReal( acc, x ) {
	return acc + x.re;
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof accumulateUnary, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function performs a reduction over a 0-dimensional ndarray', function test( t ) {
	var x;
	var v;

	x = {
		'dtype': 'float64',
		'data': new Float64Array( [ 5.0 ] ),
		'shape': [],
		'strides': [ 0 ],
		'offset': 0,
		'order': 'row-major'
	};

	v = accumulateUnary( [ x ], 0.0, add );
	t.strictEqual( v, 5.0, 'returns expected value' );
	t.end();
});

